'use strict';
const source=$('Code | Validate Privacy Request | PrivacyRequest').first().json;
const response=$input.first()?.json||{};
const body=response.body??response.data??response;
let parsed=body;
try{if(typeof body==='string')parsed=JSON.parse(body)}catch{}
const rows=Array.isArray(parsed)?parsed:[parsed];
const row=rows.find(r=>r&&String(r.request_id||r.requestId||'')===source.requestId)||null;
if(!row)throw new Error('privacy_request_receipt_missing');
const {confirmationTokenHash,...safeSource}=source;
return [{json:{...safeSource,queued:true,queueStatus:String(row.status||'pending'),confirmationProofStored:Boolean(row.confirmation_token_hash||row.confirmationTokenHash),privacyRequestReceipt:row}}];
